bool IPAModule::match(const char *name, uint32_t minVersion,
		      uint32_t maxVersion) const
{
	return info_.pipelineVersion >= minVersion &&
	       info_.pipelineVersion <= maxVersion &&
	       !strcmp(info_.name, name);
}

